// Menampilkan kembali page loader umum (#loader di _Layout) untuk proses yang
// memakan waktu dan berakhir dengan reload halaman, mis. upload Excel. Loader itu
// disembunyikan lewat kelas .is-hidden begitu halaman selesai dimuat, jadi cukup
// dikembalikan — bukan bikin spinner baru — supaya tampilannya sama persis.
// Judul/subtitel bisa diganti agar konteksnya jelas (mis. "Uploading data").
// Fallback ke #loader-modal bila panel page loader tidak ada di halaman tersebut.
function showProcessLoader(title, subtitle) {
    var $loader = $('#loader');
    if ($loader.length) {
        if (title) $loader.find('.aims-page-loader__title').text(title);
        if (subtitle) $loader.find('.aims-page-loader__subtitle').text(subtitle);
        // _Layout menyembunyikannya dua kali: kelas .is-hidden lalu .hide() setelah
        // transisi selesai. Keduanya harus dibatalkan, dan display dikembalikan ke
        // flex (nilai asli .loader) supaya panel tetap di tengah layar.
        $loader.removeClass('is-hidden').css('display', 'flex');
    } else {
        $('#loader-modal').show();
    }
    $('body').addClass('aims-loader-lock');
}

function deleteData(url) {
    //url = baseUrl + url;

    Swal.fire({
        title: 'Confirmation',
        text: "Are you sure to delete data?!",
        icon: "warning",
        buttonsStyling: false,
        showCancelButton: true,
        confirmButtonText: feather.icons['archive'].toSvg({ class: 'font-medium-1 me-50' }) + 'Yes, delete it!',
        cancelButtonText: feather.icons['x'].toSvg({ class: 'font-medium-1 me-50' }) + 'Cancel',
        customClass: {
            confirmButton: "btn btn-round btn-danger waves-effect waves-float waves-light",
            cancelButton: "btn btn-round btn-outline-secondary waves-effect waves-float waves-light ms-1"
        },
        showLoaderOnConfirm: true,
        showCancelButton: true,
        preConfirm: () => {
            $("#loader-submit").show();
            $("#button-submit").hide();
            showProcessLoader();
            return window.location.href = url;
        },
        allowOutsideClick: () => !Swal.isLoading()
    });
}

