function onUploadData(form) {
    Swal.fire({
        title: 'Are you sure?',
        text: "You won't be able to upload data!",
        icon: "warning",
        buttonsStyling: false,
        showCancelButton: true,
        confirmButtonText: feather.icons['upload'].toSvg({ class: 'font-medium-1 me-50' }) + 'Yes, upload it!',
        cancelButtonText: feather.icons['x'].toSvg({ class: 'font-medium-1 me-50' }) + 'Cancel',
        customClass: {
            confirmButton: "btn btn-round btn-warning waves-effect waves-float waves-light",
            cancelButton: "btn btn-round btn-outline-secondary waves-effect waves-float waves-light ms-1"
        },
        allowOutsideClick: () => !Swal.isLoading()
    }).then((result) => {
        if (result.isConfirmed) {
            // Upload Excel bisa berjalan lama (ribuan baris) dan halaman baru berpindah
            // setelah server selesai. Tanpa loader layar terlihat diam dan file rawan
            // dikirim dua kali.
            showProcessLoader('Uploading data', 'Please wait, your file is being processed');
            return form.submit();
        } else if (result.isDenied) {
            return false;
        }
    });
}

function onSaveData(form) {
    Swal.fire({
        title: 'Confirmation',
        text: "Are you sure to save data?",
        icon: "warning",
        buttonsStyling: false,
        showCancelButton: true,
        confirmButtonText: feather.icons['check'].toSvg({ class: 'font-medium-1 me-50' }) + 'Yes, save it!',
        cancelButtonText: feather.icons['x'].toSvg({ class: 'font-medium-1 me-50' }) + 'Cancel',
        customClass: {
            confirmButton: "btn btn-round btn-primary waves-effect waves-float waves-light",
            cancelButton: "btn btn-round btn-outline-secondary waves-effect waves-float waves-light ms-1"
        },
        allowOutsideClick: () => !Swal.isLoading()
    }).then((result) => {
        if (result.isConfirmed) {
            let $form = document.getElementById('form_sweetalert');
            // Tampilkan page loader umum (#loader) selama POST + redirect,
            // termasuk saat klik "Submit Approval". Loader hilang sendiri
            // begitu halaman hasil redirect selesai dimuat.
            showProcessLoader();
            return form.submit();
        } else if (result.isDenied) {
            return false;
        }
    });
}

