function onLogout(event, link) {
    event.preventDefault();

    Swal.fire({
        title: 'Confirmation',
        text: 'Are you sure you want to logout?',
        icon: 'warning',
        buttonsStyling: false,
        showCancelButton: true,
        showCloseButton: true,
        confirmButtonText: feather.icons['log-out'].toSvg({ class: 'font-medium-1 me-50' }) + 'Yes, logout!',
        cancelButtonText: feather.icons['x'].toSvg({ class: 'font-medium-1 me-50' }) + 'Cancel',
        customClass: {
            confirmButton: 'btn btn-round btn-danger waves-effect waves-float waves-light',
            cancelButton: 'btn btn-round btn-outline-secondary waves-effect waves-float waves-light ms-1'
        },
        didOpen: (popup) => {
            popup.querySelectorAll('.swal2-cancel, .swal2-close').forEach((button) => {
                button.addEventListener('click', (event) => {
                    event.preventDefault();
                    event.stopPropagation();

                    if (window.PtkPageLoader) {
                        window.PtkPageLoader.hide();
                    }

                    Swal.close();
                }, { once: true });
            });
        },
        allowOutsideClick: () => !Swal.isLoading()
    }).then((result) => {
        if (result.isConfirmed) {
            showProcessLoader();
            window.location.href = link.href;
            return;
        }

        if (window.PtkPageLoader) {
            window.PtkPageLoader.hide();
        }
    });

    return false;
}

document.addEventListener('click', function (event) {
    var logoutLink = event.target.closest('a.logout-confirm');
    if (!logoutLink) return;

    onLogout(event, logoutLink);
});

